rag_routes.decorator:
@router.post(
    "/canvas-module",
    response_model=BatchIngestionResult,
    responses={
        502: {"description": "Canvas request failed"},
        503: {"description": "Canvas is not configured"},
    },
)

@router.post(
    "/canvas-course",
    response_model=CourseIngestionResult,
    responses={
        400: {"description": "Invalid Canvas credentials"},
        401: {"description": "Canvas rejected the access token"},
        502: {"description": "Canvas request failed"},
        503: {"description": "Canvas is not configured"},
    },
)
